CREATE TABLE IF NOT EXISTS cms_update_history(id BIGSERIAL PRIMARY KEY,component_type VARCHAR(40) NOT NULL,component_key VARCHAR(190) NOT NULL,before_version VARCHAR(64),before_checksum VARCHAR(128),after_version VARCHAR(64),after_checksum VARCHAR(128),actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL,status VARCHAR(20) NOT NULL CHECK(status IN('started','succeeded','failed','rolled_back','quarantined')),snapshot_path TEXT,health_json TEXT NOT NULL DEFAULT '{}',error_message TEXT,started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_package_quarantine(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,version VARCHAR(64),checksum VARCHAR(128),reason TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','released')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,released_at TIMESTAMP,UNIQUE(extension_key,version,checksum));
CREATE TABLE IF NOT EXISTS cms_security_advisories(id BIGSERIAL PRIMARY KEY,advisory_key VARCHAR(190) NOT NULL UNIQUE,extension_key VARCHAR(190),affected_constraint VARCHAR(64) NOT NULL DEFAULT '*',severity VARCHAR(20) NOT NULL CHECK(severity IN('low','medium','high','critical')),title TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',action VARCHAR(20) NOT NULL DEFAULT 'warn' CHECK(action IN('warn','quarantine','block')),source VARCHAR(80) NOT NULL DEFAULT 'local',published_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_trust_scans(id BIGSERIAL PRIMARY KEY,scan_key VARCHAR(190) NOT NULL UNIQUE,checked_extensions INTEGER NOT NULL DEFAULT 0,quarantined INTEGER NOT NULL DEFAULT 0,blocked INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
